function monthlyRows(){return data.lots.map(l=>{let opening=0,incoming=0,outgoing=0;for(const m of data.movements.filter(m=>m.lot_id===l.id&&m.date.slice(0,7)<=month)){if(m.date.slice(0,7)<month||m.type==='initial')opening=decimalSum([opening,m.type==='out'?-m.grams:m.grams]);else if(m.type==='in')incoming=decimalSum([incoming,m.grams]);else outgoing=decimalSum([outgoing,m.grams])}return {...l,opening,incoming,outgoing,closing:decimalSum([opening,incoming,-outgoing])}})}
