function bind(){bindSettings();if(view==='administracion')bindAdministration(cloud);if(view==='dispositivos')bindDevices(cloud,accountAccess);main.querySelectorAll('[data-preparation-tab]').forEach(el=>el.onclick=()=>{preparationTab=el.dataset.preparationTab;render();});main.querySelectorAll('[data-pantone]').forEach(el=>el.onclick=()=>pantoneForm(Number(el.dataset.pantone)));main.querySelectorAll('[data-order-consume]').forEach(el=>el.onclick=()=>orderForm(Number(el.dataset.orderConsume)));main.querySelectorAll('[data-order-clock]').forEach(el=>el.onclick=()=>changeOrderClock(Number(el.dataset.orderClock),el.dataset.clockOperation,el));main.querySelectorAll('[data-incident-edit]').forEach(el=>el.onclick=()=>incidentForm(Number(el.dataset.incidentEdit)));main.querySelectorAll('[data-incident-pdf]').forEach(el=>el.addEventListener('click',()=>downloadIncident(Number(el.dataset.incidentPdf))));for(const [id,key] of [['incident-machine','machine'],['incident-owner','owner'],['incident-status','status']])document.getElementById(id)?.addEventListener('change',e=>{if(key==='machine')incidentMachineFilter=e.target.value;if(key==='owner')incidentOwnerFilter=e.target.value;if(key==='status')incidentStatusFilter=e.target.value;render();});main.querySelectorAll('[data-preparation]').forEach(el=>el.onclick=()=>preparationForm(Number(el.dataset.preparation)));document.querySelector('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();const el=document.querySelector('#search');el.focus();if(el.type!=='search')el.setSelectionRange(pos,pos)});for(const [id,key] of [['type-filter','type'],['provider-filter','provider'],['status-filter','status']])document.getElementById(id)?.addEventListener('change',e=>{if(key==='type')typeFilter=e.target.value;if(key==='provider')providerFilter=e.target.value;if(key==='status')statusFilter=e.target.value;page=1;render()});document.querySelector('#month')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;page=1;render()}});main.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;page=1;query='';typeFilter='';providerFilter='';statusFilter='';render()});main.querySelectorAll('[data-catalog-tab]').forEach(el=>el.onclick=()=>{catalogTab=el.dataset.catalogTab;query='';render()});main.querySelectorAll('[data-movement-tab]').forEach(el=>el.onclick=()=>{movementTab=el.dataset.movementTab;page=1;render()});main.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=Number(el.dataset.page);render()});main.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>lotDetail(Number(el.dataset.detail)));main.querySelectorAll('[data-order-detail]').forEach(el=>el.onclick=()=>orderDetail(Number(el.dataset.orderDetail)));main.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action))}
function action(a){if(a==='order-status')orderStatusLinkForm();if(a==='order-portal')orderPortalForm();if(a==='teams-connect')teamsConnectionForm();if(a==='incident')incidentForm();if(a==='preparation')preparationForm();if(a==='income')movementForm('in');if(a==='expense')movementForm('out');if(a==='product')productForm();if(a==='order')orderForm();if(a==='negative'){statusFilter='negative';page=1;render()}if(a==='export')exportPDF();if(a==='expand-all'||a==='collapse-all')main.querySelectorAll('.provider-group,.product-group').forEach(el=>el.open=a==='expand-all');if(a==='close-month')closeForm()}
function show(title,sub,body,submit='',callback){modal.classList.remove('wide-modal');modal.innerHTML=`<form id="modal-form"><div class="modal-header"><div><h2>${title}</h2><p>${sub}</p></div><button type="button" class="icon-button" data-dismiss aria-label="Cerrar">${icon('x')}</button></div><div class="modal-body">${body}<p class="form-error" id="form-error" role="alert" hidden></p></div><div class="modal-actions"><button type="button" class="btn" data-dismiss>${submit?'Cancelar':'Cerrar'}</button>${submit?`<button type="submit" class="btn primary" id="submit-button">${submit}</button>`:''}</div></form>`;modal.querySelectorAll('[data-dismiss]').forEach(el=>el.onclick=()=>modal.close());modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=modal.querySelector('#submit-button'),err=modal.querySelector('#form-error');if(!callback)return;btn.disabled=true;err.hidden=true;try{await callback(new FormData(e.target));modal.close()}catch(error){err.textContent=error.message;err.hidden=false;btn.disabled=false}};if(!modal.open)modal.showModal();translateDOM(modal,settings.language)}
